        private fun decrypt30(e: ByteArray, k: Array<ByteArray>): String {
            val c = e.copyOf()
            for (i in k.indices.reversed()) {
                for (j in c.indices) { c[j] = (c[j].toInt() xor k[i][j].toInt()).toByte() }
            }
            return c.joinToString("") { "%02X".format(it) }
        }
